public class SubrangeShufflerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String sorted(int[] a) {
        int[] copy = java.util.Arrays.copyOf(a, a.length);
        java.util.Arrays.sort(copy);
        return java.util.Arrays.toString(copy);
    }

    public static void main(String[] args) {
        int[] source = {10, 20, 30, 40, 50, 60, 70, 80};
        String untouched = "[10, 20, 30, 40, 50, 60, 70, 80]";

        try {
            check("shuffleRange(2, 6, seed 4)", "[10, 20, 30, 60, 40, 50, 70, 80]",
                    java.util.Arrays.toString(SubrangeShuffler.shuffleRange(source, 2, 6, 4L)));
            check("shuffleRange(0, 8, seed 4) shuffles everything", "[70, 20, 10, 50, 80, 40, 30, 60]",
                    java.util.Arrays.toString(SubrangeShuffler.shuffleRange(source, 0, 8, 4L)));
            check("shuffleRange(1, 5, seed 2024)", "[10, 30, 20, 50, 40, 60, 70, 80]",
                    java.util.Arrays.toString(SubrangeShuffler.shuffleRange(source, 1, 5, 2024L)));
            check("a range of length 1 changes nothing", untouched,
                    java.util.Arrays.toString(SubrangeShuffler.shuffleRange(source, 3, 4, 4L)));
            check("an empty range changes nothing", untouched,
                    java.util.Arrays.toString(SubrangeShuffler.shuffleRange(source, 3, 3, 4L)));
            SubrangeShuffler.shuffleRange(source, 2, 6, 4L);
            check("the source array is never modified", untouched, java.util.Arrays.toString(source));
            check("no value is lost or duplicated", sorted(source),
                    sorted(SubrangeShuffler.shuffleRange(source, 0, 8, 99L)));
            check("same seed gives the same result",
                    java.util.Arrays.toString(SubrangeShuffler.shuffleRange(source, 2, 6, 4L)),
                    java.util.Arrays.toString(SubrangeShuffler.shuffleRange(source, 2, 6, 4L)));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

