/**
 * Fisher-Yates shuffling restricted to a sub-range of an array.
 */
public class SubrangeShuffler {

    public static int[] shuffleRange(int[] source, int from, int to, long seed) {
        int[] copy = java.util.Arrays.copyOf(source, source.length);
        java.util.Random rng = new java.util.Random(seed);
        for (int i = to - 1; i > from; i--) {
            int j = from + rng.nextInt(i - from + 1);
            int tmp = copy[i];
            copy[i] = copy[j];
            copy[j] = tmp;
        }
        return copy;
    }
}
